REG q[64] @clk.pos PORT
  load=1 -> data
| ena=1 & amount=0 -> {q[62:0], 1'b0}
| ena=1 & amount=1 -> {q[55:0], 8'b0}
| ena=1 & amount=2 -> {1'b0, q[63:1]}
