REG predict_history[32] @clk.pos areset.pos->32'hFFFFFFFF PORT
  train_mispredicted=1 -> {train_history[30:0], train_taken}
| predict_valid=1 -> {predict_history[30:0], predict_taken}
| * -> predict_history

REG predict_history[32] @clk.pos areset.pos->0 PORT
  train_mispredicted=1 -> {train_history[30:0], train_taken}
| predict_valid=1 -> {predict_history[30:0], predict_taken}
| * -> predict_history

COMB q_next
  * -> {q[0], q[31:23], q[22] ^ q[0], q[21:3], q[2] ^ q[0], q[1] ^ q[0]}

REG q[32] @clk.pos reset.sync->32'hFFFFFFFF NEXT=q_next PORT

